#!/usr/bin/env python3
"""Small dependency-free validator for the repository's JSON Schema subset.

This intentionally implements only keywords used by incident-record.schema.json.
For production use, validate with a complete JSON Schema Draft 2020-12 library.
"""

import argparse
import datetime as dt
import json
import re
import sys
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = ROOT / "schema" / "incident-record.schema.json"


def _is_type(value, expected):
    checks = {
        "object": lambda x: isinstance(x, dict),
        "array": lambda x: isinstance(x, list),
        "string": lambda x: isinstance(x, str),
        "boolean": lambda x: isinstance(x, bool),
        "null": lambda x: x is None,
        "number": lambda x: isinstance(x, (int, float)) and not isinstance(x, bool),
        "integer": lambda x: isinstance(x, int) and not isinstance(x, bool),
    }
    if isinstance(expected, list):
        return any(_is_type(value, item) for item in expected)
    return checks[expected](value)


def _valid_format(value, fmt):
    if fmt == "date":
        try:
            dt.date.fromisoformat(value)
            return True
        except ValueError:
            return False
    if fmt == "date-time":
        try:
            parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
            return parsed.tzinfo is not None
        except ValueError:
            return False
    if fmt == "uri":
        parsed = urlparse(value)
        return parsed.scheme in ("http", "https") and bool(parsed.netloc)
    return True


def validate(instance, schema, path="$", errors=None):
    """Return a list of human-readable validation errors."""
    if errors is None:
        errors = []

    expected_type = schema.get("type")
    if expected_type and not _is_type(instance, expected_type):
        errors.append(f"{path}: expected type {expected_type}")
        return errors

    if "const" in schema and instance != schema["const"]:
        errors.append(f"{path}: expected constant {schema['const']!r}")
    if "enum" in schema and instance not in schema["enum"]:
        errors.append(f"{path}: {instance!r} is not in {schema['enum']}")

    if isinstance(instance, str):
        if "minLength" in schema and len(instance) < schema["minLength"]:
            errors.append(f"{path}: shorter than {schema['minLength']} characters")
        if "maxLength" in schema and len(instance) > schema["maxLength"]:
            errors.append(f"{path}: longer than {schema['maxLength']} characters")
        if "pattern" in schema and not re.search(schema["pattern"], instance):
            errors.append(f"{path}: does not match {schema['pattern']}")
        if "format" in schema and not _valid_format(instance, schema["format"]):
            errors.append(f"{path}: invalid {schema['format']}")

    if isinstance(instance, list):
        if "minItems" in schema and len(instance) < schema["minItems"]:
            errors.append(f"{path}: fewer than {schema['minItems']} items")
        if "items" in schema:
            for index, item in enumerate(instance):
                validate(item, schema["items"], f"{path}[{index}]", errors)

    if isinstance(instance, dict):
        for key in schema.get("required", []):
            if key not in instance:
                errors.append(f"{path}: missing required property {key!r}")
        properties = schema.get("properties", {})
        if schema.get("additionalProperties") is False:
            for key in instance:
                if key not in properties:
                    errors.append(f"{path}: unexpected property {key!r}")
        for key, value in instance.items():
            if key in properties:
                validate(value, properties[key], f"{path}.{key}", errors)

    for subschema in schema.get("allOf", []):
        if "if" in subschema:
            condition_errors = validate(instance, subschema["if"], path, [])
            branch = "then" if not condition_errors else "else"
            if branch in subschema:
                validate(instance, subschema[branch], path, errors)
        else:
            validate(instance, subschema, path, errors)

    return errors


def load_schema(path=SCHEMA_PATH):
    with Path(path).open(encoding="utf-8") as handle:
        return json.load(handle)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("records", nargs="+", type=Path)
    parser.add_argument("--schema", type=Path, default=SCHEMA_PATH)
    args = parser.parse_args(argv)
    schema = load_schema(args.schema)
    failed = False
    for path in args.records:
        try:
            with path.open(encoding="utf-8") as handle:
                record = json.load(handle)
            errors = validate(record, schema)
        except (OSError, json.JSONDecodeError) as exc:
            errors = [str(exc)]
        if errors:
            failed = True
            print(f"FAIL {path}", file=sys.stderr)
            for error in errors:
                print(f"  - {error}", file=sys.stderr)
        else:
            print(f"OK   {path}")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Apply Signal Before Harm's proposed v0.1 triage policy to JSON records."""

import argparse
import json
import sys
from pathlib import Path

MATERIAL = {"primary", "contributing", "necessary_but_not_sufficient"}
CONTROLLED = {"controlled_evaluation", "red_team"}
BARRIERS = {"human_intervention", "technical_control", "chance"}


def assess(record):
    harm = record["harm"]
    contribution = record["causal_contribution"]["model_status"]
    counterfactual = record["counterfactual"]
    occurred = harm["occurred"]
    severity = harm["severity"]
    path = counterfactual["credible_path_to_serious_harm"]
    missing = []

    sensitivity = record["sensitivity"]
    sensitive_flags = [key for key, value in sensitivity.items() if value]
    if sensitive_flags:
        missing.append(
            "Sensitive-content flags are set; stop public release and select an appropriate confidential review process."
        )

    if occurred is None:
        event_type = "unclassified_signal"
        priority = "expedited"
        rationale = "Actual-harm status is unknown; neither an incident nor a non-incident can be established."
        missing.append("What actual harm, if any, occurred, and what evidence establishes that outcome?")
    elif occurred:
        event_type = "incident"
        if severity in {"serious", "catastrophic"} and contribution in MATERIAL:
            priority = "emergency"
            rationale = "Serious or catastrophic actual harm occurred with a material model contribution."
        elif severity == "unknown":
            priority = "expedited"
            rationale = "Actual harm occurred but its severity is unresolved."
            missing.append("What severity threshold applies, and which observed facts establish it?")
        else:
            priority = "standard"
            rationale = "Actual harm occurred, but the serious-harm/material-contribution emergency conditions are not both met."
        if contribution == "unknown":
            missing.append("What evidence establishes whether the model materially contributed to the actual harm?")
    else:
        if path is None and counterfactual["applicable"]:
            missing.append("What concrete sequence and evidence support or reject a credible path to serious harm?")
        if contribution == "unknown" and path is True:
            event_type = "unclassified_signal"
            priority = "expedited"
            rationale = "A serious-harm path is claimed, but the model's causal contribution is unresolved."
            missing.append("Did the model materially contribute to the counterfactual pathway? On what evidence?")
        elif (
            counterfactual["applicable"]
            and path is True
            and contribution in MATERIAL
            and counterfactual["barrier_type"] in BARRIERS
        ):
            event_type = "near_miss"
            priority = "expedited"
            rationale = (
                "No actual harm occurred, but a materially model-involving path to serious harm "
                f"was interrupted by {counterfactual['barrier_type'].replace('_', ' ')}."
            )
        elif record["setting"] in CONTROLLED:
            event_type = "evaluation_finding"
            priority = "standard"
            rationale = "The record is a controlled-test observation without established actual harm or a supported near miss."
        else:
            event_type = "other_safety_signal"
            priority = "standard"
            rationale = "Neither actual harm nor a materially model-involving, interrupted serious-harm path is established."
        if path is True and contribution in MATERIAL and counterfactual["barrier_type"] not in BARRIERS:
            missing.append("What specific human intervention, technical control, or chance event interrupted the pathway?")

    if contribution == "not_material":
        missing.append("Confirm scope: the record states that the model was not material to the outcome.")

    return {
        "record_id": record["record_id"],
        "event_record_type": event_type,
        "review_priority": priority,
        "requires_human_review": True,
        "legal_reportability": "not_determined",
        "rationale": rationale,
        "missing_facts": missing,
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("records", nargs="+", type=Path)
    parser.add_argument("--json", action="store_true", help="emit one JSON result per line")
    args = parser.parse_args(argv)
    mismatches = 0
    for path in args.records:
        with path.open(encoding="utf-8") as handle:
            record = json.load(handle)
        result = assess(record)
        expected = record.get("expected")
        if expected:
            for key, value in expected.items():
                if result[key] != value:
                    mismatches += 1
                    print(
                        f"MISMATCH {path}: {key}: expected {value!r}, got {result[key]!r}",
                        file=sys.stderr,
                    )
        if args.json:
            print(json.dumps(result, sort_keys=True))
        else:
            print(f"{result['record_id']}: {result['event_record_type']} / {result['review_priority']}")
            print(f"  {result['rationale']}")
            for question in result["missing_facts"]:
                print(f"  ? {question}")
    return 1 if mismatches else 0


if __name__ == "__main__":
    raise SystemExit(main())

